import { Button } from "@/components/ui/button";
import AppToggle from "@/components/ui/navbar-components/app-toggle";
import TeamSwitcher from "@/components/ui/navbar-components/team-switcher";
import { SparklesIcon, UploadIcon } from "lucide-react";

const teams = ["Acme Inc.", "Origin UI", "Junon"];

export default function Component() {
	return (
		<header className="border-b px-4 md:px-6">
			<div className="flex h-16 items-center justify-between gap-4">
				{/* Left side */}
				<div className="flex flex-1 items-center gap-2">
					<TeamSwitcher teams={teams} defaultTeam={teams[0]} />
				</div>
				{/* Middle area */}
				<AppToggle />
				{/* Right side */}
				<div className="flex flex-1 items-center justify-end gap-2">
					<Button
						size="sm"
						variant="ghost"
						className="text-sm max-sm:aspect-square max-sm:p-0"
					>
						<UploadIcon
							className="opacity-60 sm:-ms-1"
							size={16}
							aria-hidden="true"
						/>
						<span className="max-sm:sr-only">Export</span>
					</Button>
					<Button
						size="sm"
						className="text-sm max-sm:aspect-square max-sm:p-0"
					>
						<SparklesIcon
							className="opacity-60 sm:-ms-1"
							size={16}
							aria-hidden="true"
						/>
						<span className="max-sm:sr-only">Upgrade</span>
					</Button>
				</div>
			</div>
		</header>
	);
}

import * as React from "react";

import { cn } from "@/registry/utilities/cn";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

"use client";

import { useId, useState } from "react";

import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";

export default function AppToggle() {
	const id = useId();
	const [selectedValue, setSelectedValue] = useState("on");

	return (
		<div className="bg-input/50 inline-flex h-8 rounded-md p-0.5">
			<RadioGroup
				value={selectedValue}
				onValueChange={setSelectedValue}
				className="group after:bg-background has-focus-visible:after:border-ring has-focus-visible:after:ring-ring/50 relative inline-grid grid-cols-[1fr_1fr] items-center gap-0 text-sm font-medium after:absolute after:inset-y-0 after:w-1/2 after:rounded-sm after:shadow-xs after:transition-[translate,box-shadow] after:duration-300 after:ease-[cubic-bezier(0.16,1,0.3,1)] has-focus-visible:after:ring-[3px] data-[state=off]:after:translate-x-0 data-[state=on]:after:translate-x-full"
				data-state={selectedValue}
			>
				<label className="group-data-[state=on]:text-muted-foreground/70 relative z-10 inline-flex h-full min-w-8 cursor-pointer items-center justify-center px-3 whitespace-nowrap transition-colors select-none">
					Sitemap
					<RadioGroupItem id={`${id}-1`} value="off" className="sr-only" />
				</label>
				<label className="group-data-[state=off]:text-muted-foreground/70 relative z-10 inline-flex h-full min-w-8 cursor-pointer items-center justify-center px-3 whitespace-nowrap transition-colors select-none">
					Wireframe
					<RadioGroupItem id={`${id}-2`} value="on" className="sr-only" />
				</label>
			</RadioGroup>
		</div>
	);
}

"use client";

import React from "react";

import { cn } from "@/registry/utilities/cn";
import * as RadioGroupPrimitive from "@radix-ui/react-radio-group";
import { Circle } from "lucide-react";

const RadioGroup = React.forwardRef<
	React.ElementRef<typeof RadioGroupPrimitive.Root>,
	React.ComponentPropsWithoutRef<typeof RadioGroupPrimitive.Root>
>(({ className, ...props }, ref) => {
	return (
		<RadioGroupPrimitive.Root
			className={cn("grid gap-2", className)}
			{...props}
			ref={ref}
		/>
	);
});
RadioGroup.displayName = RadioGroupPrimitive.Root.displayName;

const RadioGroupItem = React.forwardRef<
	React.ElementRef<typeof RadioGroupPrimitive.Item>,
	React.ComponentPropsWithoutRef<typeof RadioGroupPrimitive.Item>
>(({ className, ...props }, ref) => {
	return (
		<RadioGroupPrimitive.Item
			ref={ref}
			className={cn(
				"aspect-square h-4 w-4 rounded-full border border-primary text-primary ring-offset-background focus:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50",
				className
			)}
			{...props}
		>
			<RadioGroupPrimitive.Indicator className="flex items-center justify-center">
				<Circle className="h-2.5 w-2.5 fill-current text-current" />
			</RadioGroupPrimitive.Indicator>
		</RadioGroupPrimitive.Item>
	);
});
RadioGroupItem.displayName = RadioGroupPrimitive.Item.displayName;

export { RadioGroup, RadioGroupItem };

"use client";

import * as React from "react";

import { Button } from "@/components/ui/button";
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { ChevronsUpDown } from "lucide-react";

export default function TeamSwitcher({
	teams,
	defaultTeam,
}: {
	teams: string[];
	defaultTeam: string;
}) {
	const [selectedProject, setSelectedProject] = React.useState(defaultTeam);

	return (
		<DropdownMenu>
			<DropdownMenuTrigger asChild>
				<Button variant="ghost" className="p-0 hover:bg-transparent">
					<span className="bg-primary text-primary-foreground flex size-8 items-center justify-center rounded-full">
						{selectedProject.charAt(0).toUpperCase()}
					</span>
					<div className="flex flex-col gap-0.5 leading-none">
						<span className="">{selectedProject}</span>
					</div>
					<ChevronsUpDown size={14} className="text-muted-foreground/80" />
				</Button>
			</DropdownMenuTrigger>
			<DropdownMenuContent align="start">
				{teams.map((project) => (
					<DropdownMenuItem
						key={project}
						onSelect={() => setSelectedProject(project)}
					>
						{project}
					</DropdownMenuItem>
				))}
			</DropdownMenuContent>
		</DropdownMenu>
	);
}
